//! The generator trial (could the document be generated from the handlers?): the paths of one route group, `/apps/{app}/public-links`,
//! generated by utoipa from its handlers (`#[utoipa::path]`) and its request and answer types
//! (`ToSchema`), held to what the hand-written registry documents for them.
//!
//! What the two must agree on: the operations, their path parameters, the request body
//! (required or not, and its schema) and the success answer's schema, compared in a canonical
//! form ([`canon`]) that keeps what a client reads (properties, required, nullable, closed,
//! integer sign, item types, named components) and drops what only the prose differs in
//! (descriptions, formats). The rest of each registry entry (who may call it, the step-up,
//! the error codes and their `details`, the `x-calimero-*` extensions) has no source in the
//! handler a derive can read; [`what_the_registry_adds_is_what_no_handler_says`] pins that
//! list, so the evaluation in `docs/.../contribute/openapi.mdx` stays true.

use std::collections::BTreeSet;

use serde_json::{json, Map, Value};
use utoipa::OpenApi;

use super::super::public_links::{
    __path_public_link_create, __path_public_link_list, __path_public_link_revoke,
};

/// The browser's assertion as the registry's `#Assertion` names it: `calimero_identity::Assertion`
/// lives in another crate, which would need utoipa as a dependency to derive it there.
#[derive(utoipa::ToSchema)]
#[schema(rename_all = "camelCase")]
#[allow(dead_code, reason = "a schema only: read by the derive, never built")]
pub(in crate::api) struct Assertion {
    credential_id: String,
    authenticator_data: String,
    client_data_json: String,
    signature: String,
}

#[derive(OpenApi)]
#[openapi(paths(public_link_create, public_link_list, public_link_revoke))]
struct PublicLinksApi;

/// The operations of the group, as `(path, method)`.
const OPS: &[(&str, &str)] = &[
    ("/apps/{app}/public-links", "post"),
    ("/apps/{app}/public-links", "get"),
    ("/apps/{app}/public-links/{link}", "delete"),
];

/// The components both documents name, compared on their own.
const SHARED: &[&str] = &["Confirm", "ConfirmOnly", "Assertion"];

fn generated() -> Value {
    serde_json::to_value(PublicLinksApi::openapi()).expect("the generated document serializes")
}

/// `schema` in a form both documents agree on when they say the same to a client: a `$ref` to a
/// component the registry also names stays a reference by name; one to a component only the
/// generator names (a request or answer type the registry writes inline) is inlined.
fn canon(schema: &Value, doc: &Value) -> Value {
    let Some(o) = schema.as_object() else {
        return schema.clone();
    };
    if let Some(r) = o.get("$ref").and_then(Value::as_str) {
        let name = r.rsplit('/').next().unwrap_or_default();
        if SHARED.contains(&name) {
            return json!({ "ref": name });
        }
        return canon(&doc["components"]["schemas"][name], doc);
    }
    // `T | null`, written as a list of types or as a union with `null`.
    if let Some(types) = o.get("type").and_then(Value::as_array) {
        let rest: Vec<&Value> = types.iter().filter(|t| *t != "null").collect();
        if rest.len() < types.len() {
            let mut base = o.clone();
            let _old = base.insert("type".to_owned(), rest[0].clone());
            return json!({ "nullable": canon(&Value::Object(base), doc) });
        }
    }
    for key in ["oneOf", "anyOf"] {
        if let Some(alts) = o.get(key).and_then(Value::as_array) {
            let null = |a: &&Value| a.get("type") == Some(&json!("null"));
            let rest: Vec<&Value> = alts.iter().filter(|a| !null(a)).collect();
            if rest.len() == 1 && alts.len() == 2 {
                return json!({ "nullable": canon(rest[0], doc) });
            }
            return json!({ key: rest.iter().map(|a| canon(a, doc)).collect::<Vec<_>>() });
        }
    }
    match o.get("type").and_then(Value::as_str) {
        Some("object") => {
            let props: Map<String, Value> = o
                .get("properties")
                .and_then(Value::as_object)
                .map(|p| p.iter().map(|(k, v)| (k.clone(), canon(v, doc))).collect())
                .unwrap_or_default();
            let required: BTreeSet<&str> = o
                .get("required")
                .and_then(Value::as_array)
                .map(|r| r.iter().filter_map(Value::as_str).collect())
                .unwrap_or_default();
            json!({
                "object": props,
                "required": required,
                "closed": o.get("additionalProperties") == Some(&json!(false)),
            })
        }
        Some("array") => json!({ "array": canon(&o["items"], doc) }),
        Some("integer") => json!(if o.get("minimum") == Some(&json!(0)) {
            "uint"
        } else {
            "int"
        }),
        Some(other) => json!(other),
        None => json!("any"),
    }
}

/// An operation's path parameters, its request body and its success answer, canonical.
fn contract(op: &Value, doc: &Value) -> Value {
    let params: Vec<Value> = op
        .get("parameters")
        .and_then(Value::as_array)
        .map(|ps| {
            ps.iter()
                .map(|p| json!([p["name"], p["in"], p["required"], canon(&p["schema"], doc)]))
                .collect()
        })
        .unwrap_or_default();
    let body = op.get("requestBody").map(|b| {
        json!({
            "required": b.get("required").cloned().unwrap_or(json!(false)),
            "schema": canon(&b["content"]["application/json"]["schema"], doc),
        })
    });
    json!({
        "operationId": op["operationId"],
        "parameters": params,
        "body": body,
        "ok": canon(&op["responses"]["200"]["content"]["application/json"]["schema"], doc),
    })
}

/// Where the generated document still says something else than the registry, and why: an
/// optional body (`Option<Json<T>>`) is written as a nullable one (`T | null`), while the
/// registry, as the handler, takes no body or `T`, never `null`; the derive has no way to say
/// "optional, not nullable" of a request body.
const KNOWN: &[&str] = &["delete /apps/{app}/public-links/{link}: body"];

/// Each operation of the group says the same to a client in the generated document as in the
/// registry, and so does each component both name, but for [`KNOWN`].
#[test]
fn public_links_generated_from_their_handlers_match_the_registry() {
    let generated = generated();
    let registry = super::document();
    let mut wrong = Vec::new();
    let mut shown = Vec::new();
    for &(path, method) in OPS {
        let g = &generated["paths"][path][method];
        let r = &registry["paths"][path][method];
        assert!(g.is_object(), "the generator documents {method} {path}");
        let (g, r) = (contract(g, &generated), contract(r, &registry));
        for part in ["operationId", "parameters", "body", "ok"] {
            if g[part] != r[part] {
                wrong.push(format!("{method} {path}: {part}"));
                shown.push(format!(
                    "{method} {path}: {part}\n  generated {}\n  registry  {}",
                    g[part], r[part]
                ));
            }
        }
    }
    for name in SHARED {
        let g = canon(&generated["components"]["schemas"][name], &generated);
        let r = canon(&registry["components"]["schemas"][name], &registry);
        if g != r {
            wrong.push(format!("#{name}"));
            shown.push(format!("#{name}:\n  generated {g}\n  registry  {r}"));
        }
    }
    assert_eq!(
        wrong,
        KNOWN,
        "the generated public-links paths differ from the registry:\n{}",
        shown.join("\n")
    );
}

/// What the registry says of each operation that the generator does not: the keys only its
/// entries carry. None has a source in the handler's signature or types (who may call it, the
/// step-up, the error codes, the `x-calimero-*` extensions, the prose), so a migration keeps a
/// registry beside the derives for them.
#[test]
fn what_the_registry_adds_is_what_no_handler_says() {
    let generated = generated();
    let registry = super::document();
    let keys = |op: &Value| -> BTreeSet<String> {
        op.as_object()
            .map(|o| o.keys().cloned().collect())
            .unwrap_or_default()
    };
    let mut added = BTreeSet::new();
    let mut statuses = BTreeSet::new();
    for &(path, method) in OPS {
        let (g, r) = (
            &generated["paths"][path][method],
            &registry["paths"][path][method],
        );
        added.extend(keys(r).difference(&keys(g)).cloned());
        statuses.extend(
            keys(&r["responses"])
                .difference(&keys(&g["responses"]))
                .cloned(),
        );
    }
    let added: Vec<&str> = added.iter().map(String::as_str).collect();
    assert_eq!(
        added,
        [
            "description",
            "security",
            "x-calimero-group",
            "x-calimero-sealed",
            "x-calimero-step-up",
            "x-calimero-user-verification",
            "x-calimero-who",
        ]
    );
    let statuses: Vec<&str> = statuses.iter().map(String::as_str).collect();
    assert_eq!(
        statuses,
        ["400", "401", "403", "404", "409", "412", "421", "429"],
        "every error answer comes from the registry"
    );
}
